import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static int MAX = 1000005;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long answer = 1;
        int P = sc.nextInt();
        int K = sc.nextInt();

        if (K == 0) {
            for (int i = 1; i < P; i++) {
                answer = (answer * P) % MOD;
            }
            System.out.println(answer);
            sc.close();
            return;
        }

        int[] cycle = new int[MAX];
        int[] mark = new int[MAX];
        List<Integer> vec = new ArrayList<>();

        for (int i = 1; i < P; i++) {
            if (mark[i] == 0) {
                long next = i;
                long length = 0;
                while (mark[(int)next] == 0) {
                    mark[(int)next] = 1;
                    next = (K * next) % P;
                    length++;
                }
                cycle[(int)length]++;
                vec.add((int)length);
            }
        }

        for (int i = 0; i < vec.size(); i++) {
            long temp = (long)vec.get(i) * cycle[vec.get(i)];
            temp %= MOD;
            answer = (answer * (temp + 1)) % MOD;
        }

        if (K == 1) {
            answer = (answer * P) % MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}
